import{_ as t,o as s,a as p,b as e}from"./app.DKoEZOcr.js";const r="/ascendc.github.io/pr/5487/assets/single_iter_exp.BWoq0y7R.png",i="/ascendc.github.io/pr/5487/assets/two_iter_exp.0UwaHtHT.png",o="/ascendc.github.io/pr/5487/assets/mask_param_int32.CnmrUdok.png",n="/ascendc.github.io/pr/5487/assets/data_block_stride.ubjjNDEK.png",c="/ascendc.github.io/pr/5487/assets/single_iter_non_continuous.CXbFQigR.png",l="/ascendc.github.io/pr/5487/assets/repeat_stride1.FAN8Ia-9.png",d="/ascendc.github.io/pr/5487/assets/repeat_stride2.DM9rdlnL.png",g="/ascendc.github.io/pr/5487/assets/repeat_stride3.ByFgInLw.png",_="/ascendc.github.io/pr/5487/assets/repeat_stride4.Cjqmf_-N.png",m="/ascendc.github.io/pr/5487/assets/multi_iter_non_continuous.nCwTIGzg.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"SIMD计算说明","link":"/api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/SIMD_compute"},{"text":"高维切分","link":"/api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/high_dim_split"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/high_dim_split.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/high_dim_split.md","outlineHeaders":[{"level":2,"title":"迭代控制","slug":"迭代控制","link":"#迭代控制"},{"level":2,"title":"掩码配置","slug":"掩码配置","link":"#掩码配置"},{"level":2,"title":"地址间隔配置","slug":"地址间隔配置","link":"#地址间隔配置"}],"lastUpdated":1787050286000}'),k={name:"api/SIMD-API/basic_api/memory_vector_compute/SIMD_compute/high_dim_split.md"};function h(B,a,u,S,D,b){return s(),p("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>高维切分</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本章节对<strong>矢量计算基础API</strong>中的<strong>tensor高维切分计算</strong>接口做解释说明。如果您不需要使用此类接口，可略过该章节。</p><p>下文中的repeatTime、dataBlockStride、repeatStride、mask为通用描述，其命名不一定与具体指令中的参数命名完全对应。</p><p>比如，单次迭代内不同DataBlock间地址步长dataBlockStride参数，在单目API中，对应为dstBlkStride、srcBlkStride参数；在双目API中，对应为dstBlkStride、src0BlkStride、src1BlkStride参数。</p><p>您可以在具体接口的参数说明中，找到参数含义的描述。</p></div><p><strong>高维切分API</strong>，支持repeatTime、stride和mask参数，能控制指令的迭代执行、操作数的地址间隔和迭代内的掩码，功能更加灵活。</p><p>以Exp接口为例，接口调用形式如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">Exp</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTime</span><span class="p">,</span><span class="w"> </span><span class="p">{</span><span class="n">dstBlkStride</span><span class="p">,</span><span class="w"> </span><span class="p">...,</span><span class="w"> </span><span class="n">dstRepStride</span><span class="p">,</span><span class="w"> </span><span class="p">...});</span>
</code></pre></div><h2 id="迭代控制">迭代控制<a class="header-anchor" href="#迭代控制">​</a></h2><p>Vector计算单元每个迭代会从Unified Buffer（UB）中取出<strong>8</strong>个<strong>DataBlock</strong>（每个DataBlock数据块内部地址连续，长度为32Byte）进行计算，并写入对应的8个DataBlock中。下图为单次迭代内的8个DataBlock进行Exp计算的示意图。</p><p><strong>图1</strong> 单次迭代内的8个DataBlock进行Exp计算示意图<br><img src="`+r+'" alt><a id="图1-单次迭代内的8个datablock进行exp计算示意图"></a></p><p>矢量计算API支持开发者通过<strong>repeatTime</strong>来配置迭代次数，从而控制指令的多次迭代执行。假设repeatTime设置为2，矢量计算单元会进行2个迭代的计算，可计算出2*8（每个迭代8个DataBlock）* 32Byte = 512Byte的结果。如果数据类型为half，则计算了256个元素。下图展示了2次迭代Exp计算的示意图。由于硬件限制，<strong>repeatTime不能超过255。</strong></p><p><strong>图2</strong> 2次迭代Exp计算<br><img src="'+i+'" alt><a id="图2-2次迭代exp计算"></a></p><h2 id="掩码配置">掩码配置<a class="header-anchor" href="#掩码配置">​</a></h2><p>针对同一个迭代中的数据，可以通过<strong>mask</strong>参数进行掩码操作来控制实际参与计算的个数。下图为进行Abs计算时通过mask逐比特模式按位控制哪些元素参与计算的示意图，1表示参与计算，0表示不参与计算。关于掩码的详细介绍请参考<a href="mask.html#%E6%8E%A9%E7%A0%81">掩码</a>。</p><p><strong>图3</strong> 通过<strong>mask</strong>参数进行掩码操作示意图（以int32数据类型为例）<br><img src="'+o+'" alt><a id="图3-通过mask参数进行掩码操作示意图以int32数据类型为例"></a></p><h2 id="地址间隔配置">地址间隔配置<a class="header-anchor" href="#地址间隔配置">​</a></h2><p>矢量计算单元还支持带间隔的向量计算，通过<strong>dataBlockStride</strong>（单次迭代内不同DataBlock间地址步长）和<strong>repeatStride</strong>（相邻迭代间相同DataBlock的地址步长）来进行配置。</p><ul><li><p><strong>dataBlockStride</strong><a id="datablockstride"></a></p><p>dataBlockStride是指单次迭代内不同DataBlock间地址步长。其取值不能超过UB大小限制。</p><ul><li>连续计算，dataBlockStride设置为1，对同一迭代内的8个DataBlock数据连续进行处理。</li><li>非连续计算，dataBlockStride值大于1（如取2），同一迭代内不同DataBlock之间在读取数据时出现一个DataBlock的间隔，如下图所示。</li></ul><p><strong>图4</strong> dataBlockStride不同取值举例<br><img src="'+n+'" alt><a id="图4-datablockstride不同取值举例"></a></p><p><strong>注：dstBlkStride不支持设置为0，若设置成0可能产生未定义行为；若srcBlkStride=0，则源操作数将始终复用第一个DataBlock。</strong></p><p>下图给出了单次迭代内源操作数与目的操作数在UB空间的读写示例。示例中源操作数的dataBlockStride配置为2，表示单次迭代内不同DataBlock间地址步长为2个DataBlock；目的操作数的dataBlockStride配置为1，表示单次迭代内地址连续。</p><p><strong>图5</strong> 单次迭代内非连续场景的示意图<br><img src="'+c+'" alt><a id="图5-单次迭代内非连续场景的示意图"></a></p></li><li><p><strong>repeatStride</strong><a id="repeatstride"></a></p><p>repeatStride是指相邻迭代间相同DataBlock的地址步长。</p><ul><li><p><strong>连续计算场景：</strong> 假设定义一个Tensor供目的操作数和源操作数同时使用（即地址重叠），repeatStride取值为8。此时，矢量计算单元第一次迭代读取连续8个DataBlock，第二轮迭代读取下一个连续的8个DataBlock，通过多次迭代即可完成所有输入数据的计算。</p><p><img src="'+l+'" alt></p></li><li><p><strong>非连续计算场景：</strong> repeatStride取值大于8（如取10）时，则相邻迭代间矢量计算单元读取的数据在地址上不连续，出现2个DataBlock的间隔。</p><p><img src="'+d+'" alt></p></li><li><p><strong>反复计算场景：</strong> repeatStride取值为0时，矢量计算单元会对首个连续的8个DataBlock进行反复读取和计算。</p><p><img src="'+g+'" alt></p></li><li><p><strong>部分重复计算：</strong> repeatStride取值大于0且小于8时，相邻迭代间部分数据会被矢量计算单元重复读取和计算，此种情形一般场景不涉及。</p><p><img src="'+_+'" alt></p></li></ul><p>当repeatTime大于1，需要多次迭代完成矢量计算时，开发者可以根据不同的使用场景合理设置repeatStride的值。下图给出了多次迭代间非连续场景的示意图，示例中源操作数和目的操作数的<strong>repeatStride</strong>均配置为9，表示相邻迭代间相同DataBlock起始地址之间的间隔为9个DataBlock。相同DataBlock是指DataBlock在迭代内的位置相同，比如下图中的src1和src9处于相邻迭代，在迭代内都是第一个DataBlock的位置，其间隔即为<strong>repeatStride</strong>的数值。</p><p><strong>图6</strong> 多次迭代间非连续场景的示意图<br><img src="'+m+'" alt><a id="图6-多次迭代间非连续场景的示意图"></a></p></li></ul></article></div>',1)])])}const A=t(k,[["render",h]]);export{v as __pageData,A as default};
